/* Start::body */
body {
  font-size: $default-font-size;
  font-family: $default-font-family;
  font-weight: $default-font-weight;
  background-color: $default-body-color;
  color: $default-text-color;
  line-height: 1.5;
  text-align: start;
  overflow-x: clip;
  min-height: 100vh;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
}
/* End::body */

/* Start::Page header  */
.page-header {
  display: flex;
  align-items: center;
  margin: 1.5rem 0rem 1.5rem;
  flex-wrap: wrap;
  justify-content: space-between;
  padding: 0;
  position: relative;
  border: 1px solid transparent;
  border-radius: 5px;
  min-height: 50px;
  .page-header-bredcrumb {
    padding: 3px 15px 5px 15px;
    background: $custom-white;
    border-radius: 15px;
    .breadcrumb {
      align-items: center;
    }
    .breadcrumb-item .svg-icon {
      width: 20px;
      color: $primary-05;
      fill: $primary-05;
    }
    .breadcrumb-icon {
      margin-inline-start: 4px;
    }
  }
}
.dashboard-pageheader {
  .btn {
    position: relative;
    border: 0;
    padding: 0;
    #input {
      padding-inline-start: 40px;
    }
  }
  .header-icon2 {
    width: 20px;
    height: 20px;
    color: $primary;
    fill: $primary;
  }
}

.page-title {
  margin: 0;
  font-size: 25px;
  font-weight: 500;
  line-height: 2.5rem;
  position: relative;
}

.page-options {
  margin-inline-start: auto;
}

.page-header .breadcrumb {
  font-size: 14px;
  padding-inline-start: 0 !important;
}

/* End::Page header  */
.page {
  *::-webkit-scrollbar {
    width: 0.25rem;
    height: 0.25rem;
    transition: all ease 0.05s;
  }

  *:hover::-webkit-scrollbar-thumb {
    background: $light;
  }
}
a,
button {
  outline: 0 !important;
}

/* Start::basic */
.page {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 100vh;
}
@media (min-width: 992px) {
  .app-content {
    min-height: calc(100vh - 7.5rem);
    margin-block-end: 0;
    margin-block-start: 4.7rem;
    margin-inline-start: 250px;
    transition: margin-inline-start 0.2s ease;
  }
}
.main-content {
  padding: 0px 1rem 0 1rem;
}
/* End::basic */

/* Start::App Content */

.bd-example > .dropdown-menu {
  position: static;
  display: block;
}

/* Start::width */
.min-w-fit-content {
  min-width: fit-content;
}
/* End::width */

/* Start::Scrollspy */
.scrollspy-example {
  height: 12.5rem;
  margin-block-start: 0.5rem;
  overflow: auto;
}
.scrollspy-example-2 {
  height: 21.875;
  overflow: auto;
}
.scrollspy-example-3 {
  height: 13.75rem;
  overflow: auto;
}
.simple-list-example-scrollspy .active {
  background-color: $primary;
  color: $white;
}
.scrollspy-example-4 {
  height: 12.5rem;
  margin-block-start: 0.5rem;
  overflow: auto;
}
/* End::Scrollspy */

/* Start::Carousel */
.carousel-inner {
  border-radius: 0.35rem;
}
.carousel-caption {
  color: $white;
}
/* End::Carousel */

/* Start::navbar */
.fixed-top {
  position: static;
  margin-block-start: -1rem;
  margin-inline-end: -1rem;
  margin-block-end: 0rem;
  margin-inline-start: -1rem;
}

.fixed-bottom {
  position: static;
  margin-block-start: 1rem;
  margin-inline-end: 0rem;
  margin-block-end: -1rem;
  margin-inline-start: -1rem;
}

.sticky-top {
  position: static;
  margin-block-start: -1rem;
  margin-inline-end: -1rem;
  margin-block-end: 0rem;
  margin-inline-start: -1rem;
}
/*End::navbar*/

/* Start::Helpers */
.bd-example-ratios .ratio {
  display: inline-block;
  width: 10rem;
  color: $text-muted;
  background-color: $primary-01;
  border: $default-border;
  border-radius: $default-radius;
}

@media (min-width: 768px) {
  .bd-example-ratios-breakpoint .ratio-4x3 {
    --bs-aspect-ratio: 50%;
  }
}

.bd-example-ratios-breakpoint .ratio-4x3 {
  width: 16rem;
}
/* End::Helpers */

/* Start::Layouts */
.bd-example-row [class^="col"],
.bd-example-cssgrid .grid > * {
  padding-block-start: 0.75rem;
  padding-block-end: 0.75rem;
  background-color: rgba(var(--light-rgb), 0.75);
  border: 1px solid $default-border;
}
.bd-example-cssgrid .grid > * {
  border-radius: 0.25rem;
}
.bd-example-row-flex-cols .row {
  min-height: 10rem;
  background-color: rgba(var(--light-rgb), 0.5);
}

.grid {
  display: grid;
  grid-template-rows: repeat(var(--bs-rows, 1), 1fr);
  grid-template-columns: repeat(var(--bs-columns, 12), 1fr);
  gap: var(--bs-gap, 1.5rem);

  .g-start-2 {
    grid-column-start: 2 !important;
  }

  .g-col-2 {
    grid-column: auto/span 2;
  }

  .g-start-3 {
    grid-column-start: 3;
  }

  .g-col-3 {
    grid-column: auto/span 3;
  }

  .g-col-4,
  .g-col-md-4 {
    grid-column: auto/span 4;
  }

  .g-col-6 {
    grid-column: auto/span 6;
  }

  .g-start-6 {
    grid-column-start: 6;
  }
}
/* End::Layouts */

.callout {
  padding: 1.25rem;
  margin-block-start: 1.25rem;
  margin-block-end: 1.25rem;
  background-color: $light;
  border-inline-start: 0.25rem solid $default-border;
}

.callout-info {
  background-color: rgba(var(--info-rgb), 0.075);
  border-color: rgba(var(--info-rgb), 0.5);
}

.callout-warning {
  background-color: rgba(var(--warning-rgb), 0.075);
  border-color: rgba(var(--warning-rgb), 0.5);
}

.callout-danger {
  background-color: rgba(var(--danger-rgb), 0.075);
  border-color: rgba(var(--danger-rgb), 0.5);
}

.flex-container div {
  background-color: transparent;
  border: 0;
  > div {
    background-color: $light;
    border: 1px solid $custom-white;
  }
}

.bd-example-position-utils {
  position: relative;
  padding: 2rem;

  .position-relative {
    height: 12.5rem;
    background-color: $default-background;
  }

  .position-absolute {
    width: 2rem;
    height: 2rem;
    background-color: $primary-01;
    border-radius: 0.375rem;
  }
}
/* End::Utilities Page */

/* Start:: Images & Figures */
.bd-placeholder-img-lg {
  font-size: 3.5rem;
}
.figure-caption {
  color: $text-muted;
}
/* End:: Images & Figures */

/* End:App-Content */

/*  Start::Footer*/

[data-nav-layout="vertical"]{
    @media (min-width: 992px) {
      .footer {
        padding-inline-start: 250px !important;
      }
    }
}
.footer {
  font-size: 0.875rem;
  padding: 1rem 1.25rem;
  background-color: $custom-white;
  box-shadow: $box-shadow;
}
/*  End::Footer*/

/* Start::OffCanvas */
.offcanvas {
  background-color: $custom-white;
  color: $default-text-color;
}
.offcanvas-body {
  flex-grow: 1;
  padding: 1rem 1rem;
  overflow-y: auto;
}
/* End::OffCanvas */

/* Start::Switcher */
@keyframes spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
#switcher-main-tab {
  border-block-end: 0;
}
#switcher-canvas {
  width: 25rem;
  .offcanvas-body {
    padding: 0 0 4.75rem 0;
      height: 100vh;
  }
  .canvas-footer {
    padding: 0.75rem 1.563rem;
    position: absolute;
    inset-block-end: 0;
    width: 100%;
    background-color: $custom-white;
    border-block-start: 1px dashed $default-border;
    box-shadow: 0 0.25rem 0.5rem rgba(0, 0, 0, 0.5);
  }
  #switcher-main-tab button.nav-link {
    border-radius: 0;
    color: $default-text-color;
    font-weight: 600;
    &.active {
      color: $success;
      background-color: rgba(var(--success-rgb), 0.2);
      border-color: transparent;
    }
    &:hover {
      border-color: transparent;
    }
  }
}
.switcher-style {
  padding: 0.875rem 1.563rem;
  h6 {
    margin-block-end: 0.625rem;
  }
}
.switcher-icon .header-link-icon {
  animation-name: spin;
  animation-duration: 3000ms;
  animation-iteration-count: infinite;
  animation-timing-function: linear;
}
.switch-select {
  .form-check-label {
    font-size: 0.813rem;
    font-weight: 600;
  }
  &.form-check {
    margin-block-end: 0;
    min-height: auto;
  }
}
.menu-image {
  .bgimage-input {
    width: 3.5rem;
    height: 5.625rem;
    border-radius: $default-radius;
    border: 0;
    &.form-check-input:focus {
      border-color: transparent;
      box-shadow: 0 0 0 0.25rem $black-1;
    }
    &.bg-img1 {
      background-image: url(../images/menu-bg-images/bg-img1.jpg) !important;
      background-position: center;
      background-size: cover;
      background-repeat: no-repeat;
      &.form-check-input:checked[type="radio"] {
        background-color: none;
      }
    }
    &.bg-img2 {
      background-image: url(../images/menu-bg-images/bg-img2.jpg) !important;
      background-position: center;
      background-size: cover;
      background-repeat: no-repeat;
      &.form-check-input:checked[type="radio"] {
        background-color: none;
      }
    }
    &.bg-img3 {
      background-image: url(../images/menu-bg-images/bg-img3.jpg) !important;
      background-position: center;
      background-size: cover;
      background-repeat: no-repeat;
      &.form-check-input:checked[type="radio"] {
        background-color: none;
      }
    }
    &.bg-img4 {
      background-image: url(../images/menu-bg-images/bg-img4.jpg) !important;
      background-position: center;
      background-size: cover;
      background-repeat: no-repeat;
      &.form-check-input:checked[type="radio"] {
        background-color: none;
      }
    }
    &.bg-img5 {
      background-image: url(../images/menu-bg-images/bg-img5.jpg) !important;
      background-position: center;
      background-size: cover;
      background-repeat: no-repeat;
      &.form-check-input:checked[type="radio"] {
        background-color: none;
      }
    }
  }
}
.theme-colors {
  &.switcher-style {
    padding: 0.938rem 1.563rem;
  }
  .switch-select {
    .color-input {
      width: 2rem;
      height: 2rem;
      border-radius: 50px;
      &.form-check-input:checked {
        border: 1px solid $input-border;
        position: relative;
        box-shadow: $box-shadow;
        &:before {
          position: absolute;
          content: "\ea5e";
          font-family: tabler-icons !important;
          color: $success;
          width: 100%;
          height: 100%;
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 1.35rem;
          font-weight: 600;
        }
      }
      &.color-white {
        background-color: $white;
      }
      &.color-dark {
        background-color: $black;
      }
      &.color-primary {
        background-color: $primary;
      }
      &.color-primary-1 {
        background-color: rgb(58, 88, 146);
      }
      &.color-primary-2 {
        background-color: rgb(92, 144, 163);
      }
      &.color-primary-3 {
        background-color: rgb(161, 90, 223);
      }
      &.color-primary-4 {
        background-color: rgb(78, 172, 76);
      }
      &.color-primary-5 {
        background-color: rgb(223, 90, 90);
      }
      &.color-gradient {
        background-image: linear-gradient(to right top, $primary, #6e72a8);
      }
      &.color-transparent {
        background-image: url(../images/menu-bg-images/transparent.png) !important;
      }
      &.color-bg-1 {
        background-color: rgb(20, 30, 96);
      }
      &.color-bg-2 {
        background-color: rgb(8, 78, 115);
      }
      &.color-bg-3 {
        background-color: rgb(90, 37, 135);
      }
      &.color-bg-4 {
        background-color: rgb(24, 101, 51);
      }
      &.color-bg-5 {
        background-color: rgb(120, 66, 20);
      }
    }
    .form-check-input:checked[type="radio"] {
      background-image: none;
    }
    .form-check-input:focus {
      box-shadow: none;
    }
    .form-check-input:active {
      filter: brightness(100%);
    }
  }
}
.switcher-style-head {
  font-size: 0.8rem;
  font-weight: 600;
  margin-block-end: 0;
  background: $light;
  padding: 0.313rem 0.625rem;
  color: $default-text-color;
  .switcher-style-description {
    float: right;
    font-size: 0.625rem;
    background-color: rgba(var(--secondary-rgb), 0.2);
    color: $secondary;
    padding: 0.125rem 0.313rem;
    border-radius: $default-radius;
  }
}
#switcher-home,
#switcher-profile {
  padding: 0;
}
.theme-container-primary,
.theme-container-background {
  button {
    display: none;
  }
}
.pickr-container-primary,
.pickr-container-background {
  .pickr .pcr-button {
    width: 2rem;
    height: 2rem;
    overflow: hidden;
    border-radius: 50%;
    border: 1px solid $input-border;
    &:focus {
      box-shadow: none;
    }
    &::after {
      content: "\EFC5";
      font-family: remixicon !important;
      color: rgba($white, 0.7);
      line-height: 1.5;
      font-size: 1.25rem;
    }
  }
}
/* End::Switcher */

/* Start::Bootstrap Styles */
.h1,
.h2,
.h3,
.h4,
.h5,
.h6,
h1,
h2,
h3,
h4,
h5,
h6 {
  color: $default-text-color;
}
.card {
  background-color: $custom-white;
  color: $default-text-color;
}
.img-thumbnail {
  background-color: $custom-white;
  border: 1px solid $default-border;
}

input {
  &::placeholder {
    color: $default-text-color !important;
  }
}
/* End::Bootstrap Styles */

/* Start::Dashboard Apex Charts  */
#btcCoin,
#ethCoin,
#dshCoin,
#glmCoin {
  .apexcharts-grid,
  .apexcharts-xaxis {
    line {
      stroke: transparent;
    }
  }
}
/* Start::Dashboard Apex Charts  */

/* Start::Switcher */
@media (max-width: 991.98px) {
  .navigation-menu-styles {
    display: none;
  }
}
/* Start::Switcher */

/* Start:Responsive Dropdowns */
@media (max-width: 575.98px) {
  .cart-dropdown,
  .timelines-dropdown,
  .notifications-dropdown,
  .header-shortcuts-dropdown,
  .header-fullscreen {
    display: none !important;
  }
  .country-selector .header-link {
      margin: 5px 20px !important;
  }
}
@media (max-width: 390.98px) {
  .message-dropdown,
  .header-search {
    display: none !important;
  }
  #switcher-canvas .offcanvas-body {
      padding-bottom: 12.75rem !important;
  }
  #switcher-canvas {
      width: 20rem;
  }

}
/* End:Responsive Dropdowns */

/* Start::Close Button */
.btn-close:focus {
  box-shadow: none !important;
}
/* End::Close Button */

/* Start::Icons Page */
.icons-list {
  list-style: none;
  margin: 0 -1px -1px 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  .icons-list-item {
    text-align: center;
    height: 3rem;
    width: 3rem;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 1px solid $default-border;
    margin: 0.25rem;
    border-radius: 0.25rem;
    i {
      font-size: 1.05rem;
      color: $default-text-color;
    }
  }
}
/* End::Icons Page */

.bd-placeholder-img {
  margin: 0.125rem;
}

/* Start::Shadows */
.shadow-primary {
  box-shadow: 0 0.25rem 1rem rgba(var(--primary-rgb), 0.3) !important;
}
.shadow-secondary {
  box-shadow: 0 0.25rem 1rem rgba(var(--secondary-rgb), 0.3) !important;
}
.shadow-success {
  box-shadow: 0 0.25rem 1rem rgba(var(--success-rgb), 0.3) !important;
}
.shadow-info {
  box-shadow: 0 0.25rem 1rem rgba(var(--info-rgb), 0.3) !important;
}
.shadow-warning {
  box-shadow: 0 0.25rem 1rem rgba(var(--warning-rgb), 0.3) !important;
}
.shadow-danger {
  box-shadow: 0 0.25rem 1rem rgba(var(--danger-rgb), 0.3) !important;
}
.shadow-orange {
  box-shadow: 0 0.25rem 1rem rgba(var(--orange-rgb), 0.3) !important;
}
.shadow-purple {
  box-shadow: 0 0.25rem 1rem rgba(var(--purple-rgb), 0.3) !important;
}
/* End::Shadows */

/* Start::placeholders */
.placeholder-xl {
  min-height: 1.5em;
}
.placeholder {
  background-color: $gray-7;
}
/* End:::placeholders */

/* Start::scrollspy */
.scrollspy-example-2 {
  height: 21.875rem;
  border: 1px solid $default-border;
  padding: 0.75rem;
  border-radius: $default-radius;
}
/* End::scrollspy */

/* Start::object-fit */
.object-fit-container {
  display: flex;
  align-items: center;
  justify-content: center;
  img,
  video {
    width: 15.625rem;
    height: 15.625rem;
  }
}
/* End::object-fit */

/* Start::invoice */
.sub-panel-heading .tabs-menu ul li {
  display: block;
  width: 100%;
  border-bottom: 1px solid $default-border;
}

.sub-panel-heading .tabs-menu ul li a.active {
  background: $custom-white;
  border-radius: 0;
  width: 100%;
  color: $primary !important;
}

.sub-panel-heading .tabs-menu ul li:last-child {
  border-bottom: 0;
}

.sub-panel-heading .tabs-menu ul li a {
  padding: 15px 20px;
}

.invoicelist,
.invoicedetailspage {
  max-height: 600px;
  height: 600px;
  overflow: auto;
  border-radius: 8px;
}

@media (min-width: 992px) {
  .invoicedetailspage.tabs-menu-body {
    border-start-start-radius: 0px;
    border-start-end-radius: 8px;
    border-end-end-radius: 8px;
    border-end-start-radius: 0px;
  }
  #invoicelist {
    border-start-start-radius: 8px;
    border-start-end-radius: 0px;
    border-end-end-radius: 0px;
    border-end-start-radius: 8px;
  }
}
#invoice-list {
  .btn-link {
    color: $primary;
    text-decoration: none;
    &:hover {
      color: $primary-08;
      text-decoration: underline;
      background-color: transparent;
      border-color: transparent;
    }
  }
}
/* End::invoice */

/* Start::pricing */
.plan-card {
  .plan-icon {
    display: inline-block;
    font-size: 35px;
    width: 100px;
    height: 100px;
    color: $white;
    line-height: 76px;
    overflow: hidden;
    border: 12px solid rgba(242, 246, 249, 0.55);
    border-radius: 50%;
    transition: all 0.3s;
  }
  .plan-price {
    border-top: 1px solid $default-border;
    padding-top: 20px;
    span {
      font-size: 15px;
      vertical-align: middle;
    }
  }
  .plan-features {
    p {
      line-height: 40px;
      margin-bottom: 0;
      border-bottom: 1px solid $default-border;
      &:first-child {
        border-top: 1px solid $default-border;
      }
    }
  }
}
.pricing {
  color: $white !important;
  border-radius: 7px;
  .card-category {
    background: $white-3;
    padding: 7px 0;
    color: $white;
    border-radius: 5px;
  }
  .list-unstyled li {
    border-bottom: 1px solid $white-1;
    padding: 7px 0;
  }
}

.pricing1 {
  color: $text-muted;
  border-radius: 7px;
  .list-unstyled li {
    border-bottom: 1px solid $default-border;
    padding: 7px 0;
  }
  .card-category {
    background: $white-3;
    padding: 20px 0;
    border-radius: 7px 7px 0 0;
    color: $white;
  }
}

.pricing-table {
  width: 100%;
  margin: 0 auto;
  transition: all 0.3s ease;
  border-radius: 0px;
  &:hover {
    box-shadow: 0px 0px 30px $black-2;
    > .panel-footer-landing {
      box-shadow: 0px 0px 30px $black-05 inset;
      transition: all 0.3s ease;
    }
    > .panel {
      > .panel-body-landing {
        background: $success;
        transition: all 0.3s ease;
        > .table > tbody > tr > td {
          font-weight: 500;
          transition: all 0.3s ease;
        }
      }
      .panel-heading-landing-box {
        background: $white !important;
        color: $default-text-color !important;
        transition: all 0.3s ease;
      }
      .controle-header {
        background: $success !important;
        transition: all 0.3s ease;
        > .panel-title-landing {
          color: $white !important;
          transition: all 0.3s ease;
          font-size: 35px;
        }
      }
      .panel-footer {
        background: $success !important;
        transition: all 0.3s ease;
        text-align: center;
        > .btn {
          border: solid 1px $white !important;
          transition: all 0.3s ease;
        }
      }
    }
  }
}
.price-svg {
  position: relative;
  .price-title {
    position: absolute;
    inset-block-end: 0;
    inset-inline-start: 0;
    inset-inline-end: 0;
    text-align: center;
    color: $white;
    text-transform: uppercase;
    font-weight: 500;
    font-size: 24px;
    margin-block-end: 30px;
  }
  svg {
    height: 120px;
